"use strict";App.Pages.Login=function(){var $loginForm=$("#login-form"),$username=$("#username"),$password=$("#password");return $loginForm.on("submit",function(event){event.preventDefault();var username=$username.val(),password=$password.val();if(username&&password){var $alert=$(".alert");$alert.addClass("d-none"),App.Http.Login.validate(username,password).done(function(response){response.success?window.location.href=response.dest_url||vars("dest_url"):($alert.text(lang("login_failed")),$alert.removeClass("d-none alert-danger alert-success").addClass("alert-danger"))}).fail(function(jqXHR,textStatus,errorThrown){console.error("Error en login:",textStatus,errorThrown),console.error("Respuesta del servidor:",jqXHR.responseText);var errorMessage="Error al intentar iniciar sesi\xF3n. ";errorMessage+=0===jqXHR.status?"No se puede conectar al servidor. Verifica tu conexi\xF3n a internet.":403===jqXHR.status?"Error de CSRF token. Recarga la p\xE1gina e intenta de nuevo.":404===jqXHR.status?"P\xE1gina no encontrada. Verifica la configuraci\xF3n de la aplicaci\xF3n.":500===jqXHR.status?"Error del servidor. Verifica los logs de PHP.":"Error ".concat(jqXHR.status,": ").concat(textStatus),$alert.text(errorMessage),$alert.removeClass("d-none alert-danger alert-success").addClass("alert-danger")})}}),{}}();